import base64
import hashlib
import os
import secrets
import urllib.parse
import webbrowser
from http.server import BaseHTTPRequestHandler, HTTPServer
from typing import Dict, Optional

import requests

AUTH0_DOMAIN = os.environ.get("AUTH0_DOMAIN")
AUTH0_CLIENT_ID = os.environ.get("AUTH0_CLIENT_ID")
AUTH0_CLIENT_SECRET = os.environ.get("AUTH0_CLIENT_SECRET", "")
AUTH0_CALLBACK_URL = os.environ.get("AUTH0_CALLBACK_URL", "http://127.0.0.1:8000/callback")
AUTH0_SCOPE = os.environ.get("AUTH0_SCOPE", "openid profile email")
AUTH0_AUDIENCE = os.environ.get("AUTH0_AUDIENCE", "")

if not AUTH0_DOMAIN or not AUTH0_CLIENT_ID:
    raise RuntimeError("AUTH0_DOMAIN and AUTH0_CLIENT_ID must be set")

AUTH0_AUTHORIZE_URL = f"https://{AUTH0_DOMAIN}/authorize"
AUTH0_TOKEN_URL = f"https://{AUTH0_DOMAIN}/oauth/token"
AUTH0_USERINFO_URL = f"https://{AUTH0_DOMAIN}/userinfo"


def _b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _pkce_verifier() -> str:
    return _b64url(secrets.token_bytes(32))


def _pkce_challenge(verifier: str) -> str:
    digest = hashlib.sha256(verifier.encode("ascii")).digest()
    return _b64url(digest)


def _build_authorize_url(state: str, code_challenge: str) -> str:
    params = {
        "response_type": "code",
        "client_id": AUTH0_CLIENT_ID,
        "redirect_uri": AUTH0_CALLBACK_URL,
        "scope": AUTH0_SCOPE,
        "state": state,
        "code_challenge": code_challenge,
        "code_challenge_method": "S256",
    }
    if AUTH0_AUDIENCE:
        params["audience"] = AUTH0_AUDIENCE
    return AUTH0_AUTHORIZE_URL + "?" + urllib.parse.urlencode(params)


def _exchange_code_for_tokens(code: str, code_verifier: str) -> Dict[str, str]:
    data = {
        "grant_type": "authorization_code",
        "client_id": AUTH0_CLIENT_ID,
        "code": code,
        "redirect_uri": AUTH0_CALLBACK_URL,
        "code_verifier": code_verifier,
    }
    if AUTH0_CLIENT_SECRET:
        data["client_secret"] = AUTH0_CLIENT_SECRET

    resp = requests.post(AUTH0_TOKEN_URL, json=data, timeout=30)
    resp.raise_for_status()
    return resp.json()


def _fetch_userinfo(access_token: str) -> Dict[str, str]:
    resp = requests.get(
        AUTH0_USERINFO_URL,
        headers={"Authorization": f"Bearer {access_token}"},
        timeout=30,
    )
    resp.raise_for_status()
    return resp.json()


class _OAuthCallbackHandler(BaseHTTPRequestHandler):
    server_version = "Auth0OAuthCallback/1.0"

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        if parsed.path != urllib.parse.urlparse(AUTH0_CALLBACK_URL).path:
            self.send_response(404)
            self.end_headers()
            self.wfile.write(b"Not Found")
            return

        query = urllib.parse.parse_qs(parsed.query)
        self.server.oauth_result = {
            "code": query.get("code", [None])[0],
            "state": query.get("state", [None])[0],
            "error": query.get("error", [None])[0],
            "error_description": query.get("error_description", [None])[0],
        }

        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.end_headers()
        self.wfile.write(
            b"<html><body><h3>Login complete. You may close this tab.</h3></body></html>"
        )

    def log_message(self, format, *args):
        return


def start_oauth_login() -> Dict[str, object]:
    state = secrets.token_urlsafe(32)
    code_verifier = _pkce_verifier()
    code_challenge = _pkce_challenge(code_verifier)
    auth_url = _build_authorize_url(state, code_challenge)

    server = HTTPServer(("127.0.0.1", 8000), _OAuthCallbackHandler)
    server.oauth_result = None

    webbrowser.open(auth_url, new=1, autoraise=True)

    while server.oauth_result is None:
        server.handle_request()

    result = server.oauth_result
    if result.get("error"):
        raise RuntimeError(
            f"Authorization failed: {result.get('error')} - {result.get('error_description')}"
        )
    if result.get("state") != state:
        raise RuntimeError("State mismatch in OAuth callback")
    if not result.get("code"):
        raise RuntimeError("Missing authorization code in callback")

    token_response = _exchange_code_for_tokens(result["code"], code_verifier)
    access_token = token_response.get("access_token")
    id_token = token_response.get("id_token")

    userinfo = _fetch_userinfo(access_token) if access_token else {}

    return {
        "authorization_url": auth_url,
        "token_response": token_response,
        "id_token": id_token,
        "access_token": access_token,
        "userinfo": userinfo,
    }


if __name__ == "__main__":
    login_result = start_oauth_login()
    print(login_result)
